'open-releases':async()=>{if(window.DMOS_NATIVE?.openReleases){await window.DMOS_NATIVE.openReleases();return}const opened=window.open(RELEASE.releasesUrl,'_blank','noopener,noreferrer');if(opened===null)toast('Open '+RELEASE.releasesUrl+' in your browser.')},
'protected-save-download':()=>download('DMOS-protected-workspace.json',upgradeRaw||recoveryRaw),
'upgrade-unlock':async()=>{if(!upgradeRaw)return;if(await download('DMOS-pre-upgrade-workspace.json',upgradeRaw)===false){toast('Upgrade remains paused; the original save is unchanged.',true);return}const finish=()=>{upgradeRaw=null;initialError='';commit('Original exported. Workspace upgraded and editing enabled.')};if(typeof window.DMOS_NATIVE?.saveText==='function')finish();else confirmAction('Confirm backup saved','Check that DMOS-pre-upgrade-workspace.json has finished saving in your Downloads before continuing. Cancel keeps editing paused and the original unchanged.',finish)},
